import{_ as t,o as a,c as o,ah as s}from"./chunks/framework.ChH6X6u6.js";const p=JSON.parse('{"title":"Pilotage","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/direction/pilotage.md","filePath":"src/en/guide/direction/pilotage.md"}'),n={name:"en/guide/direction/pilotage.md"};function r(i,e,l,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="pilotage" tabindex="-1">Pilotage <a class="header-anchor" href="#pilotage" aria-label="Permalink to &quot;Pilotage&quot;">​</a></h1><p>The <strong>Pilotage</strong> page gives the school&#39;s figures — headcount, results, attendance, finances — and lets you look at them as closely as you need: a site, a level, a class. It opens from the <strong>Direction</strong> space of the menu, or from <strong>Home</strong> for an administrator.</p><p>It is part of the <strong>Pilotage</strong> module, like the <a href="/era-guide/en/guide/direction/">direction</a> profiles.</p><h2 id="choosing-what-you-look-at" tabindex="-1">Choosing what you look at <a class="header-anchor" href="#choosing-what-you-look-at" aria-label="Permalink to &quot;Choosing what you look at&quot;">​</a></h2><p>The <strong>year</strong> is the one chosen in the application header, as on the other reading screens. The page adds three filters, from the broadest to the finest:</p><ol><li>the <strong>site</strong>;</li><li>the <strong>level</strong> (6e, 5e…);</li><li>the <strong>class</strong>.</li></ol><p>Changing a filter clears the finer ones: choosing another site clears the level and the class.</p><div class="info custom-block"><p class="custom-block-title">Site director</p><p>A site director only sees their sites. If they run a single one, it is already chosen and the site filter does not appear; its name shows under the title. If they run several, they see them together, then site by site.</p></div><h2 id="the-figures" tabindex="-1">The figures <a class="header-anchor" href="#the-figures" aria-label="Permalink to &quot;The figures&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Schooling</th><th>Finances</th></tr></thead><tbody><tr><td>Students enrolled</td><td>Amount due</td></tr><tr><td>Average results</td><td>Amount collected</td></tr><tr><td>Absence rate</td><td>Recovery rate</td></tr><tr><td>Boarding occupancy</td><td>Amount disbursed</td></tr><tr><td></td><td>Net cash flow</td></tr></tbody></table><p>They are the same indicators as on the <a href="/era-guide/en/guide/admin/tableau-de-bord.html">dashboard</a>, computed the same way.</p><p><strong>Expenses</strong> and <strong>boarding</strong> belong to a site, not to a level or a class: as soon as a level or a class is chosen, those figures read &quot;—&quot;, and a line under the indicators says why.</p><h2 id="going-one-step-down" tabindex="-1">Going one step down <a class="header-anchor" href="#going-one-step-down" aria-label="Permalink to &quot;Going one step down&quot;">​</a></h2><p>The table under the figures details the chosen scope one step finer:</p><ul><li>the whole school → <strong>by site</strong>;</li><li>a site → <strong>by level</strong>;</li><li>a level → <strong>by class</strong>.</li></ul><p>Click a row&#39;s name to go down: the filter updates and the table details the next step. For a single class, there is nothing left to detail.</p><h2 id="month-by-month" tabindex="-1">Month by month <a class="header-anchor" href="#month-by-month" aria-label="Permalink to &quot;Month by month&quot;">​</a></h2><p>Two charts follow the year from the start of term to the current month:</p><ul><li><strong>money in and out</strong> each month — money out disappears below a site, for the same reason as above;</li><li>the <strong>absence rate</strong> each month, from the roll calls taken.</li></ul><p>A chart with no data at all (for instance before the first roll calls) just says so.</p><h2 id="classes-over-capacity" tabindex="-1">Classes over capacity <a class="header-anchor" href="#classes-over-capacity" aria-label="Permalink to &quot;Classes over capacity&quot;">​</a></h2><p>The last section lists the students placed in a class that was already full, within the chosen scope: the class and its site, the headcount reached (<code>31/30</code>), whether it was an admission or a transfer, the <strong>reason</strong> given, the student, who forced the assignment and the date. See <a href="/era-guide/en/guide/direction/#classes-over-capacity">Direction → Classes over capacity</a>.</p><h2 id="exporting" tabindex="-1">Exporting <a class="header-anchor" href="#exporting" aria-label="Permalink to &quot;Exporting&quot;">​</a></h2><p><strong>Export the spreadsheet</strong> downloads a CSV file with the table shown and the <strong>Total</strong> line of the chosen scope — the same filters as the page.</p>',24)])])}const u=t(n,[["render",r]]);export{p as __pageData,u as default};
